const items = $input.all();
let allJobs = [];

for (const item of items) {
  const d = item.json;

  // ── JSearch (object with d.data array) ───────────────────────────────────
  // /search-v2 wraps results as data.jobs; /search returned a bare data array.
  if (d.data && (Array.isArray(d.data) || Array.isArray(d.data.jobs))) {
    for (const j of (Array.isArray(d.data) ? d.data : d.data.jobs)) {
      allJobs.push({
        job_id:      'jsearch_' + j.job_id,
        title:       j.job_title || '',
        company:     j.employer_name || '',
        location:    j.job_is_remote ? 'Remote' : [j.job_city, j.job_state].filter(Boolean).join(', '),
        city:        j.job_city || '',
        state:       j.job_state || '',
        is_remote:   j.job_is_remote === true,
        apply_url:   j.job_apply_link || '',
        description: (j.job_description || '').substring(0, 3000),
        salary_min:  j.job_min_salary || null,
        salary_max:  j.job_max_salary || null,
        salary_text: '',
        posted_date: j.job_posted_at_timestamp
          ? new Date(j.job_posted_at_timestamp * 1000).toISOString().split('T')[0] : '',
        source: 'JSearch'
      });
    }
  }

  // ── Adzuna (results array + count number) ────────────────────────────────
  else if (d.results && Array.isArray(d.results) && typeof d.count === 'number') {
    for (const j of d.results) {
      allJobs.push({
        job_id:      'adzuna_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     (j.company && j.company.display_name) || '',
        location:    (j.location && j.location.display_name) || '',
        // area = ["US", "Washington", "Nearby County", "Nearby City A"]
        state:       (j.location && j.location.area && j.location.area[1]) || '',
        city:        (j.location && j.location.area && j.location.area.length > 2) ? j.location.area[j.location.area.length - 1] : '',
        // "remote" alone also matches "remote access VPN"; now that on-site jobs
        // are kept, remote has to mean the job is remote.
        is_remote:   /\bremote\b/i.test(j.title || '') || /\bremote\b/i.test((j.location && j.location.display_name) || '')
                  || /\b(fully remote|100% remote|remote (position|role|opportunity|work|first)|work from home|remote-first)\b/i.test(j.description || ''),
        apply_url:   j.redirect_url || '',
        description: (j.description || '').substring(0, 3000),
        salary_min:  j.salary_min || null,
        salary_max:  j.salary_max || null,
        salary_text: '',
        posted_date: j.created ? j.created.split('T')[0] : '',
        source: 'Adzuna'
      });
    }
  }

  // ── The Muse (results array + page number) ───────────────────────────────
  else if (d.results && Array.isArray(d.results) && typeof d.page === 'number') {
    for (const j of d.results) {
      if (!j.name) continue;
      allJobs.push({
        job_id:      'muse_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.name || '',
        company:     (j.company && j.company.name) || '',
        location:    'Remote',
        is_remote:   true,
        apply_url:   (j.refs && j.refs.landing_page) || '',
        description: (j.contents || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: '',
        posted_date: j.publication_date ? j.publication_date.split('T')[0] : '',
        source: 'TheMuse'
      });
    }
  }

  // ── Remotive (jobs array) ─────────────────────────────────────────────────
  else if (d.jobs && Array.isArray(d.jobs)) {
    for (const j of d.jobs) {
      allJobs.push({
        job_id:      'remotive_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     j.company_name || '',
        location:    j.candidate_required_location || 'Remote',
        is_remote:   true,
        apply_url:   j.url || '',
        description: (j.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: j.salary || '',
        posted_date: j.publication_date ? j.publication_date.split('T')[0] : '',
        source: 'Remotive'
      });
    }
  }

  // ── Indeed via RapidAPI (hits array) ─────────────────────────────────────
  else if (d.hits && Array.isArray(d.hits)) {
    for (const j of d.hits) {
      allJobs.push({
        job_id:      'indeed_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     j.company || '',
        location:    (j.location||'').toLowerCase().includes('remote') ? 'Remote' : (j.location || ''),
        is_remote:   (j.location||'').toLowerCase().includes('remote')
                  || ((j.title||'') + ' ' + (j.description||j.summary||'')).toLowerCase().includes('remote'),
        apply_url:   j.url || j.link || '',
        description: (j.description || j.summary || j.snippet || '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: j.salary || '',
        posted_date: j.date || j.datePosted || '',
        source: 'Indeed'
      });
    }
  }



  // ── LinkedIn Job Search API (active-jb-24h) — array of rich objects ───────
  else if (Array.isArray(d) && d.length > 0 && d[0].date_posted !== undefined && d[0].organization !== undefined) {
    for (const j of d) {
      if (!j.title) continue;

      // Build location string
      const locs = j.locations_derived || [];
      const locStr = locs.length > 0 ? locs[0] : '';

      // Remote detection: remote_derived flag, location_type TELECOMMUTE, or "remote" in loc/description
      const descLower = (j.description_text || '').toLowerCase().substring(0, 500);
      const isRemote = j.remote_derived === true
        || j.location_type === 'TELECOMMUTE'
        || locStr.toLowerCase().includes('remote')
        || descLower.includes('remote');

      // Salary: salary_raw is a structured object {value: [{value, unitText, currency, ...}]}
      let salMin = null, salMax = null, salText = '';
      if (j.salary_raw && j.salary_raw.value) {
        const vals = j.salary_raw.value;
        if (vals.length === 1) {
          salMin = vals[0].value || null;
          salText = vals[0].currency ? `${vals[0].currency} ${vals[0].value}` : String(vals[0].value || '');
        } else if (vals.length >= 2) {
          salMin = Math.min(...vals.map(v => v.value || 0).filter(v => v > 0)) || null;
          salMax = Math.max(...vals.map(v => v.value || 0)) || null;
        }
      }

      allJobs.push({
        job_id:      'linkedin_' + (j.id || Math.random().toString(36).substr(2, 9)),
        title:       j.title || '',
        company:     j.organization || '',
        location:    isRemote ? 'Remote' : locStr,
        is_remote:   isRemote,
        apply_url:   j.external_apply_url || j.url || '',
        description: (j.description_text || '').substring(0, 3000),
        salary_min:  salMin,
        salary_max:  salMax,
        salary_text: salText,
        posted_date: j.date_posted ? j.date_posted.split('T')[0] : '',
        source: 'LinkedIn'
      });
    }
  }


  // ── LinkedIn individual job object (n8n splits array → one item per job) ──
  else if (d.linkedin_id !== undefined && d.organization !== undefined && d.title) {
    const locs = d.locations_derived || [];
    const locStr = locs.length > 0 ? locs[0] : '';
    const descLower = (d.description_text || '').toLowerCase().substring(0, 500);
    const isRemote = d.remote_derived === true
      || d.location_type === 'TELECOMMUTE'
      || locStr.toLowerCase().includes('remote')
      || descLower.includes('remote');

    let salMin = null, salMax = null, salText = '';
    if (d.salary_raw && d.salary_raw.value) {
      const vals = d.salary_raw.value;
      if (vals.length === 1) {
        salMin = vals[0].value || null;
        salText = vals[0].currency ? `${vals[0].currency} ${vals[0].value}` : String(vals[0].value || '');
      } else if (vals.length >= 2) {
        salMin = Math.min(...vals.map(v => v.value || 0).filter(v => v > 0)) || null;
        salMax = Math.max(...vals.map(v => v.value || 0)) || null;
      }
    }

    allJobs.push({
      job_id:      'linkedin_' + d.id,
      title:       d.title || '',
      company:     d.organization || '',
      location:    isRemote ? 'Remote' : locStr,
      is_remote:   isRemote,
      apply_url:   d.external_apply_url || d.url || '',
      description: (d.description_text || '').substring(0, 3000),
      salary_min:  salMin,
      salary_max:  salMax,
      salary_text: salText,
      posted_date: d.date_posted ? d.date_posted.split('T')[0] : '',
      source: 'LinkedIn'
    });
  }

  // ── Remote OK (top-level array, element 0 is legal notice) ───────────────
  // ── Remote OK (individual job objects — n8n split the array) ─────────────
  else if (d.position !== undefined && d.company !== undefined) {
    allJobs.push({
      job_id:      'remoteok_' + (d.id || Math.random().toString(36).substr(2,9)),
      title:       d.position || '',
      company:     d.company || '',
      location:    'Remote',
      is_remote:   true,
      apply_url:   d.apply_url || d.url || '',
      description: (d.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
      salary_min:  d.salary_min ? parseInt(d.salary_min) : null,
      salary_max:  d.salary_max ? parseInt(d.salary_max) : null,
      salary_text: '',
      posted_date: d.date ? d.date.split('T')[0] : '',
      source: 'RemoteOK'
    });
  }

  else if (Array.isArray(d)) {
    for (const j of d.slice(1)) {
      if (!j || !j.position) continue;
      allJobs.push({
        job_id:      'remoteok_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.position || '',
        company:     j.company || '',
        location:    'Remote',
        is_remote:   true,
        apply_url:   j.apply_url || j.url || '',
        description: (j.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  j.salary_min ? parseInt(j.salary_min) : null,
        salary_max:  j.salary_max ? parseInt(j.salary_max) : null,
        salary_text: '',
        posted_date: j.date ? j.date.split('T')[0] : '',
        source: 'RemoteOK'
      });
    }
  }
}

// ── 2026-10-10 local + remote filter (patch_lanes_local.py) ─────────────────
// Everything above this line is the live per-source parsing, unchanged except
// that JSearch and Adzuna now carry city/state. Below: work mode, location
// allowlist, exclusions, dedup. Every drop is counted in filter_stats so a run
// shows exactly where jobs went.
const __stats = { in: allJobs.length, kept_remote: 0, kept_local: 0, dropped: {} };
const __drop = (why) => { __stats.dropped[why] = (__stats.dropped[why] || 0) + 1; return false; };

// Remote anywhere in the US, or on-site/hybrid in Your County, the
// Metro Area, or ~50 miles of Your City. Each city is pinned to its state so
// Nearby Town 5 OH, Nearby Town 6 CA, Nearby City C MS, Nearby Town 2 AZ do not pass. Nearby Town 8 and
// Nearby Town 12 are additions to the requested list (both inside the commute area).
const CITY_STATE = {
  'your city': 'WA', 'nearby town 1': 'WA', 'nearby town 2': 'WA', 'nearby town 3': 'WA',
  'nearby town 4': 'WA', 'nearby town 5': 'WA', 'nearby town 6': 'WA', 'nearby town 7': 'WA',
  'nearby city c': 'WA', 'nearby town 9': 'WA', 'nearby city a': 'WA', 'nearby city b': 'WA',
  'nearby town 8': 'WA', 'metro area': 'WA', 'metro area': 'WA',
  'nearby town 10': 'OR', 'nearby town 10': 'OR', 'nearby town 11': 'OR', 'nearby town 12': 'OR',
};
const STATE_RE = { WA: /\b(wa|washington)\b/i, OR: /\b(or|oregon)\b/i };
// JSearch labels Washington D.C. jobs "Nearby City B, Washington" (measured 2026-10-04).
const DC_HINT = /washington,?\s*d\.?\s*c\b|\bd\.c\.|\bdc metro|\bdmv area\b/i;

function localCity(j) {
  // Structured city/state first (JSearch, Adzuna), then the free-text location.
  const tryPair = (city, stateText) => {
    const c = (city || '').toLowerCase().trim();
    const st = CITY_STATE[c];
    return st && STATE_RE[st].test(stateText || '') ? c : null;
  };
  let c = tryPair(j.city, j.state);
  if (!c) {
    const loc = (j.location || '').toLowerCase();
    for (const name of Object.keys(CITY_STATE).sort((a, b) => b.length - a.length)) {
      if (new RegExp('(^|[^a-z])' + name + '([^a-z]|$)').test(loc) && STATE_RE[CITY_STATE[name]].test(loc)) { c = name; break; }
    }
  }
  if (!c) return null;
  if (DC_HINT.test(j.title + ' ' + (j.description || '').substring(0, 2500))) return null;
  return c.replace(/\b\w/g, ch => ch.toUpperCase());
}

// Whole-word match (plural allowed): 'saic' does not hit Mosaic, 'rtx' not Artex.
const kwHit = (txt, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&') + '(e?s)?([^a-z0-9]|$)').test(txt);

const DEV_TITLES = [
  'software engineer','software developer','software development',
  'web developer','web engineer','frontend','front-end','back-end','backend',
  'full stack','fullstack','full-stack',
  'mobile developer','ios developer','android developer',
  'data engineer','data scientist','ml engineer','machine learning',
  'application developer','application engineer',
  'java developer','python developer','ruby developer','rails developer',
  'react engineer','angular engineer','ui engineer','ux engineer',
  'staff engineer','principal software',
];
// Network / infrastructure / sysadmin / network-security first. SRE, platform
// and observability titles still pass (growth path) and are scored on substance.
const TITLE_OK = [
  'network engineer','network administrator','network operations','network analyst',
  'network specialist','network technician','network security','network and systems',
  'systems and network','network/systems','network architect','firewall engineer',
  'infrastructure engineer','infrastructure administrator','infrastructure operations',
  'it infrastructure','infrastructure architect',
  'systems engineer','systems administrator','system administrator','sysadmin','it systems',
  'virtualization engineer','vmware engineer','server engineer','server administrator',
  'data center engineer','wireless engineer','noc engineer','security engineer',
  'it engineer','it administrator','senior engineer','security operations',
  'hybrid cloud','cloud engineer','cloud network','cloud operations','operations engineer',
  'platform engineer','devops','dev ops','sre','site reliability','reliability engineer',
  'monitoring engineer','observability engineer','monitoring administrator',
];
const CODE_PRIMARY = [
  'building scalable web application','develop backend service',
  'full-stack development','experience with react is required',
  'ruby on rails','django framework','.net development','java spring boot',
  'mobile application development','design and develop software product',
  'software development lifecycle is your','you will write and maintain code',
];
// Clearance: title always; body only on "must hold/obtain" phrasings, so
// "no clearance required" does not trip it.
const CLEARANCE_BODY = [
  'clearance required','requires clearance','must have clearance','active secret',
  'top secret','ts/sci','secret clearance','security clearance is required',
  'clearance is required','active clearance','maintain a security clearance',
  'maintain a clearance','obtain a security clearance','eligible for a security clearance',
  'public trust clearance','public trust position','dod 8570','dod 8140',
  'iat level ii','iat level iii',
];
// DoD/defense primes, federal contractors (regional federal site, national labs) and the VA.
// State and local government is fine.
const FED_EMPLOYERS = [
  'lockheed martin','raytheon','rtx','northrop grumman','booz allen','general dynamics',
  'l3harris','bae systems','leidos','saic','caci','mantech','peraton','gdit',
  'huntington ingalls','textron','anduril','shield ai','palantir','parsons',
  'amentum','federal reserve','apogee','feditc',
  'federal it consulting','department of veterans affairs','veterans affairs',
  'veterans health administration',
];
// Narrow on purpose: "As a federal contractor..." sits in most large employers' EEO text.
const FED_BODY = [
  'department of energy','doe contract','national laboratory',
  'dod customer','support of the dod','support of dod','department of defense',
  'federal customer','federal government client','federal agency client',
  'supporting federal agencies','va medical center','veterans affairs medical',
];
// National backbone / MPLS carriers. Regional ISPs are left to the scorer.
const CARRIERS = [
  'lumen','centurylink','level 3','verizon','at&t','zayo','cogent','windstream',
  'frontier communications','gtt communications','crown castle',
];
const DRUG = ['drug test','drug screen','drug-free workplace','drug free workplace',
  'pre-employment drug','background and drug','controlled substance test'];

const DAY = 86400000;
const NOW = Date.now();
const STALE_DAYS = 14;

allJobs = allJobs.filter(j => {
  const t = (j.title || '').toLowerCase();
  const co = (j.company || '').toLowerCase();
  const body = (j.description || '').toLowerCase();

  // Work mode + location. Boards geotag remote jobs to a city ("Remote Business
  // Systems Administrator", JSearch: on-site Nearby City B), so a remote title wins.
  if (!j.is_remote && /\bremote\b/.test(t) && !/\bnot remote\b|\bnon-remote\b/.test(t)) j.is_remote = true;
  const city = j.is_remote ? '' : localCity(j);
  if (!j.is_remote && !city) return __drop('on-site outside area');
  j.city = city || '';
  j.work_mode = j.is_remote ? 'Remote' : (/\bhybrid\b/.test(t + ' ' + body) ? 'Hybrid' : 'On-site');

  if (DEV_TITLES.some(k => t.includes(k))) return __drop('dev title');
  if (!TITLE_OK.some(k => t.includes(k))) return __drop('title not infra/network');
  if (CODE_PRIMARY.some(k => body.substring(0, 1000).includes(k))) return __drop('coding-primary');

  j.clearance_flag = t.includes('clearance') || /\bts\/sci\b|\bsecret\b/.test(t)
    || CLEARANCE_BODY.some(k => body.includes(k));
  if (j.clearance_flag) return __drop('clearance');
  if (FED_EMPLOYERS.some(k => kwHit(co, k)) || FED_BODY.some(k => body.includes(k))) return __drop('federal/defense/VA');
  if (CARRIERS.some(k => kwHit(co, k))) return __drop('carrier');

  // Boards without a date filter (Remotive, RemoteOK, Muse) keep serving old
  // postings; past the dedup window they would be re-scored as new.
  if (j.posted_date) {
    const age = (NOW - Date.parse(j.posted_date)) / DAY;
    if (age > STALE_DAYS) return __drop('posted > 14 days ago');
  }

  // Drug testing is a flag, never a filter.
  j.drug_test_flag = DRUG.some(k => body.includes(k));
  return true;
});

// Dedup: job_id and company+title+city, both for 14 days.
const sd = $getWorkflowStaticData('global');
sd.seenJobIds = sd.seenJobIds || {};
sd.seenKeys = sd.seenKeys || {};
sd.companyRemote = sd.companyRemote || {};
sd.remoteLookup = sd.remoteLookup || {};
for (const m of [sd.seenJobIds, sd.seenKeys]) for (const k of Object.keys(m)) if (m[k] < NOW - 14 * DAY) delete m[k];
for (const m of [sd.companyRemote, sd.remoteLookup]) for (const k of Object.keys(m)) if ((m[k].at || 0) < NOW - 90 * DAY) delete m[k];

const normCo = s => (s || '').toLowerCase().replace(/[.,]/g, ' ')
  .replace(/\b(inc|llc|ltd|corp|corporation|co|company|the)\b/g, ' ').replace(/\s+/g, ' ').trim();

// Passive remote evidence: any remote posting seen from an employer counts.
for (const j of allJobs) if (j.work_mode === 'Remote' && j.company) {
  sd.companyRemote[normCo(j.company)] = { at: NOW };
}

const fresh = [];
for (const j of allJobs) {
  const key = (j.company + '|' + j.title + '|' + j.city).toLowerCase();
  if (sd.seenJobIds[j.job_id] || sd.seenKeys[key]) { __drop('already seen (14d)'); continue; }
  sd.seenJobIds[j.job_id] = NOW;
  sd.seenKeys[key] = NOW;
  fresh.push(j);
}

// Local jobs are rare, so they go first and are never cut by the cap.
fresh.sort((a, b) => (a.work_mode === 'Remote') - (b.work_mode === 'Remote'));
const CAP = 20;
const limited = fresh.slice(0, CAP);
if (fresh.length > CAP) __stats.dropped['over cap (20)'] = fresh.length - CAP;
for (const j of limited) j.work_mode === 'Remote' ? __stats.kept_remote++ : __stats.kept_local++;

// On-site/hybrid employers with no cached answer get one remote-history lookup.
const lookups = [];
for (const j of limited) {
  if (j.work_mode === 'Remote' || !j.company) continue;
  const k = normCo(j.company);
  if (sd.companyRemote[k] || sd.remoteLookup[k]) continue;
  if (!lookups.includes(j.company)) lookups.push(j.company);
}

return [{ json: { jobs: limited, count: limited.length, lookups: lookups.slice(0, 8), filter_stats: __stats } }];

const resp = $input.first().json;
const { jobs } = $('Format Claude Prompt').first().json;

if (!jobs || jobs.length === 0) {
  return [{ json: { noJobs: true, message: 'No new jobs this run.' } }];
}

let scores = [];
try {
  const raw = ((resp.content || []).find(b => b.type === 'text') || {}).text || '';
  let cleaned = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  const arrStart = cleaned.indexOf('[');
  const arrEnd   = cleaned.lastIndexOf(']');
  if (arrStart !== -1 && arrEnd !== -1 && arrEnd > arrStart) {
    cleaned = cleaned.substring(arrStart, arrEnd + 1);
  }
  scores = JSON.parse(cleaned);
} catch(e) {
  scores = jobs.map((j, i) => ({
    index: i + 1, score: 50,
    fit_summary: 'Auto-scored (parse error).',
    missing_skills: 'Unknown', red_flags: 'None',
    tags: [], role_type: 'Other',
    resume_tips: ['Review job description manually.'],
    cover_letter_hook: 'Please review this position and customize your cover letter accordingly.'
  }));
}

return jobs.map((job, i) => {
  const s = scores.find(x => x.index === i + 1) || {
    score: 50, fit_summary: 'Not scored.',
    missing_skills: 'Unknown', red_flags: 'None',
    tags: [], role_type: 'Other',
    resume_tips: [], cover_letter_hook: ''
  };
  return { json: {
    ...job,
    score:             s.score,
    fit_summary:       s.fit_summary,
    missing_skills:    s.missing_skills,
    red_flags:         s.red_flags,
    tags:              Array.isArray(s.tags) ? s.tags : [],
    role_type:         s.role_type || 'Other',
    size_estimate:     s.size_estimate || 'Unknown',
    clearance_flag:    job.clearance_flag === true || s.clearance_flag === true,
    drug_test_flag:    job.drug_test_flag === true || s.drug_test_flag === true,
    resume_tips:       Array.isArray(s.resume_tips) ? s.resume_tips : [s.resume_tips || ''],
    cover_letter_hook: s.cover_letter_hook || ''
  }};
});

// Needs these Notion properties (added 2026-10-10): Work Mode (select),
// City (text), Remote History (text), Drug Test Flag (select), Employer Size (text).
const THRESHOLD = 70;
const results = [];
const today = new Date().toISOString().split('T')[0];

function descBlocks(text) {
  const blocks = [];
  const safe = (text || '').substring(0, 9500);
  if (!safe) {
    return [{object:'block',type:'paragraph',paragraph:{rich_text:[{type:'text',text:{content:'(no description available)'}}]}}];
  }
  for (let i = 0; i < safe.length; i += 1900) {
    blocks.push({
      object:'block', type:'paragraph',
      paragraph:{rich_text:[{type:'text',text:{content:safe.substring(i, i+1900)}}]}
    });
  }
  return blocks;
}

function h2(text) {
  return {object:'block',type:'heading_2',heading_2:{rich_text:[{type:'text',text:{content:text}}]}};
}
function divider() { return {object:'block',type:'divider',divider:{}}; }
function bullet(text) {
  return {object:'block',type:'bulleted_list_item',
    bulleted_list_item:{rich_text:[{type:'text',text:{content:text.substring(0,2000)}}]}};
}
function para(text) {
  return {object:'block',type:'paragraph',
    paragraph:{rich_text:[{type:'text',text:{content:(text||'').substring(0,2000)}}]}};
}
const rt = (s, n) => [{ text: { content: String(s || '').substring(0, n) } }];

for (const item of $input.all()) {
  const j = item.json;

  if (j.noJobs || !j.title) continue;
  if (j.score < THRESHOLD) continue;

  const tips = Array.isArray(j.resume_tips)
    ? j.resume_tips.filter(t => t && t !== 'None')
    : [];

  const children = [
    h2('📋 Full Job Description'),
    ...descBlocks(j.description),
    divider(),
    h2('🎯 Resume Customization Tips'),
    ...(tips.length > 0
      ? tips.slice(0,8).map(t => bullet(t))
      : [para('No specific tips generated.')]),
    divider(),
    h2('✉️ Cover Letter Hook'),
    para(j.cover_letter_hook || 'Not generated.'),
  ];

  const priority = j.score >= 80 ? 'High' : 'Medium';
  const tagsValue = [{name: '🛡 Security Lane'}].concat((j.tags || []).slice(0, 9).map(t => ({name: String(t).replace(/,/g, ' ').substring(0,100)})));
  const tipsShort = tips.slice(0,3).join(' | ').substring(0,500) || 'None';
  const clShort   = (j.cover_letter_hook || 'None').substring(0,500);

  const body = {
    parent: { database_id: "YOUR_NOTION_DB_SECURITY" },
    properties: {
      "Job Title":          { title:        rt(j.title, 200) },
      "Company":            { rich_text:    rt(j.company, 200) },
      "Source":             { select:       { name: j.source || 'JSearch' } },
      "Apply URL":          { url: j.apply_url || null },
      "Location":           { rich_text:    rt(j.location, 200) },
      "Salary Min":         { number: j.salary_min || null },
      "Salary Max":         { number: j.salary_max || null },
      "Score":              { number: j.score || 0 },
      "Fit Summary":        { rich_text:    rt(j.fit_summary, 2000) },
      "Missing Skills":     { rich_text:    rt(j.missing_skills || 'None', 500) },
      "Red Flags":          { rich_text:    rt(j.red_flags || 'None', 500) },
      "Tags":               { multi_select: tagsValue },
      "Role Type":          { select:       { name: j.role_type || 'Other' } },
      "Priority":           { select:       { name: priority } },
      "Resume Tips":        { rich_text:    rt(tipsShort, 500) },
      "Cover Letter Draft": { rich_text:    rt(clShort, 500) },
      "Status":             { select:       { name: 'New' } },
      "Date Found":         { date:         { start: today } },
      "Posted Date":        { rich_text:    rt(j.posted_date, 50) },
      "Job ID":             { rich_text:    rt(j.job_id, 200) },
      "Work Mode":          { select:       { name: j.work_mode || 'Remote' } },
      "City":               { rich_text:    rt(j.city, 100) },
      "Remote History":     { rich_text:    rt(j.remote_history, 200) },
      "Drug Test Flag":     { select:       { name: j.drug_test_flag ? 'Yes' : 'No' } },
      "Employer Size":      { rich_text:    rt(j.size_estimate, 100) }
    },
    children: children
  };

  results.push({ json: { ...j, notionBody: JSON.stringify(body) } });
}

return results;

const THRESHOLD = 70;
const items = $input.all().filter(it => it && it.json && !it.json.noJobs && typeof it.json.score === 'number' && it.json.score >= THRESHOLD);
if (!items.length) {
  return []; // no qualifying (score >= 70) jobs — stay silent, no ping
}

const sorted = [...items].sort((a,b) => b.json.score - a.json.score);
const top5  = sorted.slice(0, 5);
const top20 = sorted.slice(0, 20);
const today = new Date().toLocaleDateString('en-US',
  {weekday:'long',year:'numeric',month:'long',day:'numeric'});
const NOTION = 'https://www.notion.so/YOUR_NOTION_DB_URL';

function cleanUrl(url) {
  try { return url.split('?')[0]; } catch(e) { return url; }
}
const where = j => j.work_mode === 'Remote' ? 'Remote' : `${j.work_mode} · ${j.city || '?'}`;
const salary = j => j.salary_min
  ? '$' + Math.round(j.salary_min/1000) + 'k-' + Math.round((j.salary_max||j.salary_min)/1000) + 'k'
  : (j.salary_text || 'salary not listed');
const flags = j => [
  j.drug_test_flag ? '💊 drug test' : '',
  j.work_mode !== 'Remote' && /^Yes/.test(j.remote_history || '') ? '🏠 has remote roles' : '',
  /over 10,?000/i.test(j.size_estimate || '') ? '🏢 10k+ employees' : '',
].filter(Boolean);

const srcEmoji = {
  JSearch:'🔷', Adzuna:'🟢', Remotive:'🟣', Indeed:'🔶',
  RemoteOK:'⚫', TheMuse:'🌸', LinkedIn:'🔵'
};

// ── Discord ───────────────────────────────────────────────────────────────────
let discord = `**🔍 Job Scout (Security) — ${today}** | ${items.length} match(es) ≥${THRESHOLD}

`;
for (const item of top5) {
  const j = item.json;
  const badge = srcEmoji[j.source] || '⚪';
  const summary = (j.fit_summary || '').length > 100 ? j.fit_summary.substring(0,97) + '...' : (j.fit_summary || '');
  const f = flags(j);
  const line = `**${j.score}** — **${j.title}** @ ${j.company} ${badge}
📍 ${where(j)} · \`${salary(j)}\`${f.length ? ' · ' + f.join(' · ') : ''}
${summary}
${cleanUrl(j.apply_url)}

`;
  if ((discord + line).length < 1800) discord += line;
}
discord += `📋 Email has full report | [Notion](<${NOTION}>)\n👉 **Open Notion → change Status to Applied when you apply!**`;

// ── Email ─────────────────────────────────────────────────────────────────────
let emailRows = '';
for (const item of top20) {
  const j = item.json;
  const sal = j.salary_min
    ? '$' + j.salary_min.toLocaleString() + (j.salary_max ? '-$' + j.salary_max.toLocaleString() : '+')
    : (j.salary_text || 'Not listed');
  const c = j.score >= 80 ? '#2d8a4e' : '#d4940a';
  const modeColor = j.work_mode === 'Remote' ? '#2980b9' : '#8e44ad';
  const tagHtml = j.tags && j.tags.length
    ? '<span style="margin-top:4px;display:block">'
      + j.tags.slice(0,6).map(t => `<span style="background:#e8f4f8;color:#2980b9;padding:2px 6px;border-radius:10px;font-size:11px;margin-right:3px">${t}</span>`).join('')
      + '</span>'
    : '';
  const f = flags(j);
  emailRows += '<tr style="border-bottom:1px solid #eee">'
    + `<td style="padding:12px;width:60px;text-align:center"><span style="background:${c};color:white;padding:4px 8px;border-radius:12px;font-weight:bold">${j.score}</span>`
    + `<br><span style="font-size:11px;color:#999">${j.source}</span></td>`
    + `<td style="padding:12px"><strong><a href="${j.apply_url}" style="color:#2c3e50;text-decoration:none">${j.title}</a></strong><br>`
    + `<span style="color:#666">${j.company}</span> &nbsp;|&nbsp; `
    + `<span style="color:${modeColor};font-size:13px;font-weight:bold">${where(j)}</span> &nbsp;|&nbsp; `
    + `<span style="color:#27ae60;font-size:13px">${sal}</span><br>`
    + `<span style="color:#888;font-size:12px">Size: ${j.size_estimate || 'Unknown'} &nbsp;|&nbsp; Remote history: ${j.remote_history || 'n/a'} &nbsp;|&nbsp; Drug test: ${j.drug_test_flag ? '<b style="color:#c0392b">mentioned</b>' : 'not mentioned'}</span>`
    + (f.length ? `<br><span style="font-size:12px">${f.join(' &nbsp; ')}</span>` : '')
    + `<span style="color:#555;font-size:13px;display:block;margin-top:4px">${j.fit_summary}</span>`
    + tagHtml
    + `<span style="color:#e67e22;font-size:12px;display:block;margin-top:3px">`
    + (j.resume_tips && j.resume_tips.length ? '📝 ' + (j.resume_tips[0]||'') : '') + '</span>'
    + (j.missing_skills && j.missing_skills !== 'None' ? `<span style="color:#e67e22;font-size:12px">⚠ Missing: ${j.missing_skills}</span>` : '')
    + (j.red_flags && j.red_flags !== 'None' ? `<span style="color:#e74c3c;font-size:12px;display:block">🚩 ${j.red_flags}</span>` : '')
    + `<span style="color:#aaa;font-size:12px"> Posted: ${j.posted_date||'Unknown'}</span>`
    + '</td></tr>';
}

// Filter counts for this run, so it is visible that local jobs get through.
let statsHtml = '';
try {
  const s = $('Normalize + Filter + Dedup').first().json.filter_stats;
  const d = Object.entries(s.dropped || {}).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';
  statsHtml = `<p style="color:#888;font-size:12px">This run: ${s.in} jobs in → ${s.kept_remote} remote + ${s.kept_local} local sent to scoring. Dropped — ${d}.</p>`;
} catch (e) {}

const emailHtml = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:850px;margin:0 auto;color:#333">
<h2 style="color:#2c3e50;border-bottom:3px solid #3498db;padding-bottom:10px">🔍 Job Scout (Security) — ${today}</h2>
<p>Found <strong>${items.length} job(s) scoring ${THRESHOLD}+</strong>. Showing top ${Math.min(20,items.length)}. <a href="${NOTION}">View all in Notion →</a></p>
<table style="width:100%;border-collapse:collapse">
<thead><tr style="background:#3498db;color:white"><th style="padding:10px">Score</th><th style="padding:10px;text-align:left">Job Details</th></tr></thead>
<tbody>${emailRows}</tbody></table>
${statsHtml}
<p style="margin-top:20px;color:#888;font-size:13px">
  <strong>Tip:</strong> Jobs scoring 80+ are high priority — open their Notion page for tailored resume tips and cover letter draft.
</p>
</body></html>`;

return [{ json: {
  discord_content: discord,
  email_html:      emailHtml,
  email_subject:   `Job Scout (Security): ${items.length} match(es) — ${today}`,
  has_jobs: true
} }];

// Emit this call's token spend to InfluxDB. Runs as a side branch off the
// Claude node so the pipeline is never gated on a cost write.
// Pricing mirrors scripts/log-ai-cost.sh in the NOLA repo - USD per 1M tokens,
// verified 2026-08-26.
const resp = $input.first().json;
const u = resp.usage || {};

const model        = resp.model || 'unknown';
const inputTokens  = u.input_tokens  || 0;
const outputTokens = u.output_tokens || 0;
// Present only when the request used prompt caching.
const cacheRead    = u.cache_read_input_tokens     || 0;
const cacheWrite   = u.cache_creation_input_tokens || 0;

let inCpm, outCpm;
if      (model.includes('haiku'))    { inCpm =  1.00; outCpm =  5.00; }
else if (model.includes('sonnet-5')) { inCpm =  2.00; outCpm = 10.00; }
else if (model.includes('sonnet'))   { inCpm =  3.00; outCpm = 15.00; }
else if (model.includes('opus'))     { inCpm =  5.00; outCpm = 25.00; }
else if (model.includes('fable'))    { inCpm = 10.00; outCpm = 50.00; }
else                                 { inCpm =  1.00; outCpm =  5.00; }

// tokens * (USD per 1M) lands directly in micro-dollars, which keeps the field
// an integer in InfluxDB. Cache reads bill at 0.1x input, writes at 1.25x (5m TTL).
const micro = Math.round(
  inputTokens  * inCpm  +
  outputTokens * outCpm +
  cacheRead    * inCpm * 0.10 +
  cacheWrite   * inCpm * 1.25
);

const esc = s => String(s).replace(/[ ,=]/g, '\\$&');

const line =
  `ai_cost,workflow=${esc('job-scout-security')},model=${esc(model)} ` +
  `input_tokens=${inputTokens}i,output_tokens=${outputTokens}i,` +
  `cache_read_tokens=${cacheRead}i,cache_write_tokens=${cacheWrite}i,` +
  `cost_microdollars=${micro}i ${Date.now() * 1000000}`;

return [{ json: { line, model, micro } }];

// One item per on-site/hybrid employer that needs a remote-history lookup.
const { lookups } = $input.first().json;
return lookups.map(company => ({ json: { company, query: `${company} remote` } }));

// Record each lookup's yes/no per employer (cached 90 days in static data) and
// label every job's remote history. Runs on both IF branches; when no lookup
// ran, the two node references below throw and are treated as empty.
const src = $('Normalize + Filter + Dedup').first().json;
const sd = $getWorkflowStaticData('global');
sd.remoteLookup = sd.remoteLookup || {};
sd.companyRemote = sd.companyRemote || {};
const NOW = Date.now();
const normCo = s => (s || '').toLowerCase().replace(/[.,]/g, ' ')
  .replace(/\b(inc|llc|ltd|corp|corporation|co|company|the)\b/g, ' ').replace(/\s+/g, ' ').trim();

let companies = [], results = [];
try { companies = $('Companies To Check').all().map(i => i.json.company); } catch (e) {}
try { results = $('Remote History Lookup').all(); } catch (e) {}

companies.forEach((company, i) => {
  const r = results[i] && results[i].json;
  // /search-v2 wraps results as data.jobs; /search returned a bare data array.
  const list = r && r.data && (Array.isArray(r.data) ? r.data : r.data.jobs);
  if (!Array.isArray(list)) return;   // failed/429 lookup: not cached, retried next run
  const want = normCo(company);
  // Whole normalized name must match, so "City of Nearby City C" is not "City of Nearby City B".
  const hits = list.filter(x => x.job_is_remote === true && normCo(x.employer_name) === want);
  sd.remoteLookup[want] = { at: NOW, hasRemote: hits.length > 0, count: hits.length };
});

const jobs = (src.jobs || []).map(j => {
  let remote_history;
  if (j.work_mode === 'Remote') remote_history = 'Remote role';
  else {
    const k = normCo(j.company);
    const c = sd.remoteLookup[k];
    if (sd.companyRemote[k]) remote_history = 'Yes - remote posting seen';
    else if (c && c.hasRemote) remote_history = `Yes - ${c.count} remote posting(s) found`;
    else if (c) remote_history = 'No remote postings found';
    else remote_history = 'Not checked';
  }
  return { ...j, remote_history };
});
return [{ json: { jobs, count: jobs.length, filter_stats: src.filter_stats } }];
